import{_ as s,C as r,o as a,c as n,j as t,a as i,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const l="/screenshots/vscode-run-control-hover.png",p="/screenshots/vscode-run-control-paused-page.png",c="/diagrams/run-control.svg",P=JSON.parse('{"title":"Pause and step from the editor","description":"Pause and step a Playwright run from VS Code or a JetBrains IDE, follow its stopped line and watch or interact with its headless page in the editor.","frontmatter":{"title":"Pause and step from the editor","description":"Pause and step a Playwright run from VS Code or a JetBrains IDE, follow its stopped line and watch or interact with its headless page in the editor.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-run-control.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-run-control.html"}],["meta",{"property":"og:title","content":"Pause and step from the editor | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Pause and step a Playwright run from VS Code or a JetBrains IDE, follow its stopped line and watch or interact with its headless page in the editor."}]]},"headers":[],"relativePath":"features/editor-run-control.md","filePath":"features/editor-run-control.md","lastUpdated":1794490413000}'),u={name:"features/editor-run-control.md"};function g(w,e,m,f,b,k){const o=r("Needs");return a(),n("div",null,[e[0]||(e[0]=t("h1",{id:"pause-and-step-from-the-editor",tabindex:"-1"},[i("Pause and step from the editor "),t("a",{class:"header-anchor",href:"#pause-and-step-from-the-editor","aria-label":'Permalink to "Pause and step from the editor"'},"​")],-1)),h(o,{reporter:"",fixtures:""}),e[1]||(e[1]=d('<p>A test run the <a href="./editors.html">editor extensions</a> start can be paused, stepped and resumed from the editor, with Piwi&#39;s own commands: no debug session starts, and the IDE&#39;s debugger works as usual beside it; so can <a href="./terminal-runs.html">one started outside Piwi</a>. The editor marks the line the test stopped at, as a debugger does, and the breakpoints you set or remove reach the run while it goes on. The page&#39;s <a href="./editor-breakpoints.html#pause-a-run">pause bar</a> and Piwi Picker&#39;s <a href="./runs-window.html">Runs window</a> answer the same stops. At a stop, the editor also writes code from the page: <a href="./editor-stop-code.html">Code from a pause</a>.</p><h2 id="the-controls" tabindex="-1">The controls <a class="header-anchor" href="#the-controls" aria-label="Permalink to &quot;The controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th><th>VS Code</th><th>JetBrains IDEs</th></tr></thead><tbody><tr><td><strong>Pause</strong></td><td>Stops a running test before its next call that acts on, reads or checks the page</td><td>none</td><td>Pause Program&#39;s</td></tr><tr><td><strong>Resume</strong></td><td>Runs the stopped test on to the next breakpoint</td><td><code>F5</code></td><td>Resume Program&#39;s, <code>F9</code></td></tr><tr><td><strong>Step</strong></td><td>Runs the call and stops before the next one, breakpoint or not</td><td><code>F10</code></td><td>Step Over&#39;s, <code>F8</code></td></tr><tr><td><strong>Run to cursor</strong></td><td>Stops at the first call on the cursor&#39;s line (on a statement broken over lines, at its call), or at a breakpoint before it</td><td><code>Ctrl+F10</code></td><td>Run to Cursor&#39;s, <code>Alt+F9</code></td></tr><tr><td><strong>Finish</strong></td><td>Runs the test on without stopping at a breakpoint again in this attempt</td><td><code>Shift+F11</code></td><td>Step Out&#39;s, <code>Shift+F8</code></td></tr><tr><td><strong>End the test</strong></td><td><a href="./end-the-test.html">Skips the rest of the test</a>, and a stopped locator call from Playwright 1.62</td><td>none</td><td>none</td></tr><tr><td><strong>Stop</strong></td><td>Ends the run&#39;s process</td><td><code>Shift+F5</code></td><td><strong>Stop the Run</strong>, or the Run tool window&#39;s Stop</td></tr></tbody></table><p>The keys are the IDE&#39;s debugger keys (in a JetBrains IDE, <a href="./jetbrains.html">your keymap&#39;s</a>), Piwi&#39;s only while their control applies and the debugger does not take them. On macOS, <code>Cmd+F10</code> runs to the cursor in VS Code. <strong>Pause</strong> and <strong>End the test</strong> have no key in VS Code: bind one in <strong>Preferences: Open Keyboard Shortcuts</strong> (search <code>piwi</code>). Within two seconds of an answer, until that worker stops, a key answers no other worker and starts no debug session.</p><ul><li><strong>In VS Code</strong>, the controls sit in the status bar beside the run&#39;s progress while they apply (<code>Pausing…</code> until a test stops), in the palette (<strong>Piwi: Pause the run</strong> and its kin) and the editor title (Resume, the rest under <code>…</code>).</li><li><strong>In a JetBrains IDE</strong>, they are under <strong>Tools → Piwi</strong>, enabled while they apply, and in the status bar item&#39;s menu, whose text starts <code>Piwi: paused · checkout.page.ts:12</code> while a test is stopped.</li></ul><p>The progress beside them comes from the run, so it counts offline and with the desktop app (<a href="./watch-a-run.html#how-far-it-is">Watch a run</a>); its tooltip names the other tools that have the run open.</p><p><strong>Pause</strong> stops every run Piwi started in this window (in a JetBrains IDE, this project), each worker before its next call that Playwright&#39;s debugger stops at (<a href="./editor-breakpoints.html#limits">which calls</a>): a long call or a <code>waitForTimeout</code> finishes first, unless you <a href="./end-the-test.html#while-a-pause-waits-for-a-call">end the test there</a>, and a worker between tests stops at the next test&#39;s first call. A test that never stops, under CI or Playwright&#39;s own debugger, says why.</p><h2 id="where-the-test-stands" tabindex="-1">Where the test stands <a class="header-anchor" href="#where-the-test-stands" aria-label="Permalink to &quot;Where the test stands&quot;">​</a></h2><p>When a test stops, at a breakpoint, after <strong>Step</strong> or <strong>Pause</strong>, on the line it was run to, at <code>page.pause()</code>, or at <a href="./editor-stop-code.html#a-failure">a failure</a>, the editor opens the file of the call about to run, with the cursor on its line, and marks it: an arrow in the gutter, the debugger&#39;s execution point color, and above it the call, as Playwright names it, with the controls:</p><p><code>Stopped at a breakpoint · Fill &quot;MORNING10&quot; getByLabel(&#39;Coupon code&#39;) · attempt 2</code> Resume Step Run to cursor Finish End test</p><p>It says <a href="./watch-a-run.html#where-a-test-stopped">why the test stopped</a>; <code>attempt 2</code> shows on a retry. VS Code&#39;s CodeLens holds Resume, Step, Finish and <strong>Write code…</strong>, its hover all controls; the color is <code>piwi.executionPointBackground</code>. In a JetBrains IDE the line is an inlay whose words are links, the arrow&#39;s click lists the controls, and the color is <strong>Settings → Editor → Color Scheme → Piwi → Line a run is stopped at</strong>. The mark goes when the test goes on (from the editor or the bar), ends, or closes its page.</p><figure><img src="'+l+'" alt="VS Code: a test paused at a page object&#39;s line, its hover naming the call that runs next with Resume, Step, Run to cursor and Finish, and Resume, Step and Finish above the line and in the status bar"><figcaption>A run paused before it types the coupon.</figcaption></figure><p>With several workers stopped, each has its own mark. A stop takes the cursor only on the worker you last answered or worked on, or as the first shown while no step waits; another opens beside your editor, or, in a busy JetBrains IDE, waits in the status bar&#39;s menu. The controls above a line act on its worker, a key or command on the one at the cursor&#39;s line, else the only one shown, else it asks which. A control answers the stop it was shown for: when the test went on meanwhile, it says so and asks nothing.</p><p>The run&#39;s code is your files as they stood when it started. The mark follows lines you add or remove above it, and <strong>Run to cursor</strong> in an edited file runs to the run&#39;s line for the cursor&#39;s; on a line written since, it says the test has none.</p><h2 id="a-headless-run" tabindex="-1">A headless run <a class="header-anchor" href="#a-headless-run" aria-label="Permalink to &quot;A headless run&quot;">​</a></h2><p>A run Piwi starts with breakpoints is headed, with a pause bar. Without breakpoints it follows your config, headless by default. A headless stop opens <strong>Piwi: paused page</strong> beside VS Code&#39;s editor, or <strong>Paused Page</strong> in the JetBrains Piwi tool window, which keeps its stop until it goes on, and after a <strong>Step</strong> or <strong>Run to cursor</strong> from the editor waits up to 10 seconds for its next stop. <strong>Piwi: Show the paused page</strong> (<strong>Tools → Piwi → Show the Paused Page</strong>) opens it at any stop.</p><figure><img src="'+p+'" alt="VS Code: a headless test paused before it clicks Apply, and beside the editor the Piwi: paused page tab showing the cart page with the coupon typed in"><figcaption>A headless run paused before it clicks Apply: the page at the stop, beside the editor.</figcaption></figure><p>Clicking the image picks a locator when the reporter supports it, on Playwright 1.60 or later: it replaces the stopped line&#39;s, and the tab shows the result or refusal.</p><p><strong>Watch live</strong> updates the paused page until you hide or close the tab, resume or switch stops. Choose <a href="./watch-running-test.html#interact"><strong>Interact</strong></a> to click, scroll or type on it; your first one drives the stop. Interact stays on through the worker&#39;s stops, and goes off, giving the stop back, on Escape outside a pick or check, another <a href="/guide/concepts.html#worker">lane</a>&#39;s stop, a stop without input, <strong>Watch live</strong> off or refused, the tab hidden or closed, or the run&#39;s end. The caption names who drives and watches the stop (<a href="/guide/concepts.html#presence-driving-a-stop">driving a stop</a>). The preview uses the editor&#39;s connection: no Picker, pairing, live-view setting or port forwarding. Older reporters keep the still image. To watch the test before it stops: <a href="./watch-running-test.html">Watch a running test</a>.</p><h2 id="breakpoints-while-the-run-goes-on" tabindex="-1">Breakpoints while the run goes on <a class="header-anchor" href="#breakpoints-while-the-run-goes-on" aria-label="Permalink to &quot;Breakpoints while the run goes on&quot;">​</a></h2><p>A breakpoint you add, remove or toggle applies to the run from its next call, in every worker, later ones included. One that only moves because you edited the lines above it keeps the line the run has, and one you set in an edited file applies to that line of the run&#39;s code. The breakpoints that count are those a run&#39;s start reads: line breakpoints in script files under a Playwright config&#39;s folder, while <code>piwi.breakpoints</code> (<strong>Pause the runs Piwi starts at the editor&#39;s breakpoints</strong> in a JetBrains IDE) is on. A logpoint, or a breakpoint that does not suspend, never stops the test; a condition is not read, so a conditional breakpoint stops at each pass.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><figure><img src="'+c+'" alt="A test run&#39;s workers report to the editor service through the run channel, which the IDE and Piwi Picker (over a WebSocket) steer; the pause bar shows in the test&#39;s browser only at a stop"></figure><p>With a reporter newer than 0.59.0, each worker of a Piwi run stays connected to the editor service, through a socket on your machine only you can read (<code>PIWI_RUN_CHANNEL</code>): it says which test it runs and where it stops, and the editor answers. Closing the IDE closes the connections: a stop with no pause bar then goes on, one the bar shows waits there.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>No mark on a breakpoint that never stops.</strong> One on a line with no call Playwright&#39;s debugger stops at looks like any other and does nothing.</li><li><strong>Playwright calls, not JavaScript.</strong> <strong>Step</strong> goes from one Playwright call to the next; stepping through the test&#39;s code stays with the IDE&#39;s debugger.</li><li><strong>No image when the page is unknown.</strong> A stop at a call other than a locator&#39;s (a navigation, a key press) in a browser context with several pages has no image, and refuses Piwi Picker&#39;s <strong>Pick</strong> and <strong>Record</strong>: the worker cannot tell its page. Any page of that context closing ends it.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-breakpoints.html">Breakpoints in the browser</a>: the breakpoints a run starts with, and the pause bar.</li><li><a href="./editor-runs.html">Runs from the editor</a>: the commands that start a run, and how the editor follows it.</li><li><a href="./share-live.html">Share a run live</a>: let a teammate watch a run Piwi started, from the editor.</li><li><a href="./debug-in-editor.html">Debug in my editor</a>: such a run, started from a failure&#39;s page.</li><li><a href="/guide/remote-development.html">Remote development</a>: remote windows and JetBrains Gateway.</li></ul>',28))])}const v=s(u,[["render",g]]);export{P as __pageData,v as default};
